"""v16 patch, part B: runs on CORE-PR-HANDOFF-v16.md written by part A. Same rules: every anchor must match once."""
import sys
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
p = ROOT / "CORE-PR-HANDOFF-v16.md"
s = p.read_text(encoding="utf-8")
def R(old, new, n=1):
    global s
    c = s.count(old)
    if c != n: print(f"MISMATCH expected {n} got {c}: {old[:80]!r}"); sys.exit(1)
    s = s.replace(old, new)
def before_line(prefix, text):
    global s
    L = s.split("\n"); h = [i for i, l in enumerate(L) if l.startswith(prefix)]
    if len(h) != 1: print(f"LINE MISMATCH {len(h)}: {prefix[:60]!r}"); sys.exit(1)
    L.insert(h[0], text); s = "\n".join(L)
def append_line(prefix, text):
    global s
    L = s.split("\n"); h = [i for i, l in enumerate(L) if l.startswith(prefix)]
    if len(h) != 1: print(f"LINE MISMATCH {len(h)}: {prefix[:60]!r}"); sys.exit(1)
    L[h[0]] = L[h[0]] + text; s = "\n".join(L)

